                     STRUCT('Turkey' AS raw_title, 'Turkey' AS title, 'No' AS country_flag),
                     STRUCT('Turkmenistan' AS raw_title, 'Turkmenistan' AS title, 'No' AS country_flag),
                     STRUCT('Turks & Caicos Islands' AS raw_title, 'Turks and Caicos Islands' AS title, 'No' AS country_flag),
                     STRUCT('Turks and Caicos Islands' AS raw_title, 'Turks and Caicos Islands' AS title, 'No' AS country_flag),
                     STRUCT('Tuvalu' AS raw_title, 'Tuvalu' AS title, 'No' AS country_flag),
                     STRUCT('Türkiye' AS raw_title, 'Turkey' AS title, 'No' AS country_flag),
                     STRUCT('U.S. Virgin Islands' AS raw_title, 'U.S. Virgin Islands' AS title, 'No' AS country_flag),
                     STRUCT('US' AS raw_title, 'United States' AS title, 'Yes' AS country_flag),
                     STRUCT('USA' AS raw_title, 'United States' AS title, 'Yes' AS country_flag),
                     STRUCT('Uganda' AS raw_title, 'Uganda' AS title, 'No' AS country_flag),
                     STRUCT('Ukraine' AS raw_title, 'Ukraine' AS title, 'No' AS country_flag),
                     STRUCT('United Arab Emirates' AS raw_title, 'United Arab Emirates' AS title, 'Yes' AS country_flag),
                     STRUCT('United Kingdom' AS raw_title, 'United Kingdom' AS title, 'Yes' AS country_flag),
                     STRUCT('United States' AS raw_title, 'United States' AS title, 'Yes' AS country_flag),
                     STRUCT('United States Minor Outlying Islands' AS raw_title, 'United States Minor Outlying Islands' AS title, 'No' AS country_flag),
                     STRUCT('Uruguay' AS raw_title, 'Uruguay' AS title, 'No' AS country_flag),
                     STRUCT('Uzbekistan' AS raw_title, 'Uzbekistan' AS title, 'No' AS country_flag),
                     STRUCT('Vanuatu' AS raw_title, 'Vanuatu' AS title, 'No' AS country_flag),
                     STRUCT('Vatican City' AS raw_title, 'Holy See (Vatican City State)' AS title, 'No' AS country_flag),
                     STRUCT('Venezuela' AS raw_title, 'Venezuela' AS title, 'No' AS country_flag),
                     STRUCT('Viet Nam' AS raw_title, 'Vietnam' AS title, 'No' AS country_flag),
                     STRUCT('Vietnam' AS raw_title, 'Vietnam' AS title, 'No' AS country_flag),
                     STRUCT('Virgin Islands, British' AS raw_title, 'British Virgin Islands' AS title, 'No' AS country_flag),
                     STRUCT('Virgin Islands, U.S.' AS raw_title, 'U.S. Virgin Islands' AS title, 'No' AS country_flag),
                     STRUCT('Wales' AS raw_title, 'United Kingdom' AS title, 'Yes' AS country_flag),
                     STRUCT('Wallis and Futuna' AS raw_title, 'Wallis and Futuna' AS title, 'No' AS country_flag),
                     STRUCT('Western Sahara' AS raw_title, 'Western Sahara' AS title, 'No' AS country_flag),
                     STRUCT('Yemen' AS raw_title, 'Yemen' AS title, 'No' AS country_flag),
                     STRUCT('Zambia' AS raw_title, 'Zambia' AS title, 'No' AS country_flag),
                     STRUCT('Zimbabwe' AS raw_title, 'Zimbabwe' AS title, 'No' AS country_flag),
                     STRUCT('Åland Islands' AS raw_title, 'Finland' AS title, 'Yes' AS country_flag)
                     ])
             ),
             rawData AS (
                 SELECT
                     JSON_VALUE(`data`, '$.id') AS id,
                     domain,
                     JSON_VALUE(`data`, '$.primary_domain') AS primary_domain,
                     JSON_VALUE(`data`, '$.industry') AS industry,
                     CAST(JSON_VALUE(`data`, '$.estimated_num_employees') AS INT64) AS estimated_num_employees,
                     JSON_VALUE(`data`, '$.country') AS country,
                     createdAt
                 FROM `@project.datamint.enrichment_data_raw`
                 WHERE `data` IS NOT NULL
                 QUALIFY ROW_NUMBER() OVER(PARTITION BY domain ORDER BY createdAt DESC) = 1
             ),
             formattedData AS (
                 SELECT
                     id,
                     domain,
                     IFNULL(TRIM(LOWER(primary_domain)), domain) AS primary_domain,
                     IF(TRIM(industry) = '', NULL, industry) AS industry,
                     estimated_num_employees,
                     TRIM(country) AS country,
                     createdAt
                 FROM rawData
             ),
             normalized AS (
                 SELECT
                     u.domain,
                     id.title AS industry,
                     id.is_sql_size AS industry_is_sql_size,
                     cd.title AS country,
                     cd.country_flag AS country_flag,
                     CASE
                         WHEN u.estimated_num_employees > 10000 THEN '9. 10,001+'
                         WHEN u.estimated_num_employees BETWEEN 5001 AND 10000 THEN '8. 5,001-10,000'
                         WHEN u.estimated_num_employees BETWEEN 1001 AND 5000 THEN '7. 1,001-5,000'
                         WHEN u.estimated_num_employees BETWEEN 501 AND 1000 THEN '6. 501-1,000'
                         WHEN u.estimated_num_employees BETWEEN 201 AND 500 THEN '5. 201-500'
                         WHEN u.estimated_num_employees BETWEEN 51 AND 200 THEN '4. 51-200'
                         WHEN u.estimated_num_employees BETWEEN 11 AND 50 THEN '3. 11-50'
                         WHEN u.estimated_num_employees BETWEEN 2 AND 10 THEN '2. 2-10'
                         WHEN u.estimated_num_employees <= 1 THEN '1. 0-1'
                         WHEN u.estimated_num_employees IS NULL THEN NULL
                         END AS size,
                     u.createdAt
                 FROM formattedData u
                          LEFT JOIN industry_dict id ON id.raw_key = LOWER(TRIM(u.industry))
                          LEFT JOIN country_dict  cd ON cd.raw_key = LOWER(TRIM(u.country))
             )
        SELECT domain, industry, size, country, country_flag, industry_is_sql_size, createdAt
        FROM normalized
        QUALIFY ROW_NUMBER() OVER(PARTITION BY domain ORDER BY createdAt DESC) = 1
    ) S
    ON T.domain = S.domain
    WHEN MATCHED THEN UPDATE SET
        industry = S.industry,
        size = S.size,
        country = S.country,
        country_flag = S.country_flag,
        industry_is_sql_size = S.industry_is_sql_size,
        createdAt = S.createdAt
    WHEN NOT MATCHED THEN INSERT (domain, industry, size, country, country_flag, industry_is_sql_size, createdAt)
        VALUES (S.domain, S.industry, S.size, S.country, S.country_flag, S.industry_is_sql_size, S.createdAt);
